// Progressive enhancement for content generated by tools/sync.
// Everything renders without this script; it only adds search/filter/sort,
// relative "synced" times with a staleness warning, and broken-image cleanup.
(function () {
    'use strict';

    // ── Sync health indicator ────────────────────────────────
    function relative(ms) {
        var mins = Math.round(ms / 60000);
        if (mins < 1) return 'just now';
        if (mins < 60) return mins + ' min ago';
        var hrs = Math.round(mins / 60);
        if (hrs < 48) return hrs + ' hour' + (hrs === 1 ? '' : 's') + ' ago';
        var days = Math.round(hrs / 24);
        return days + ' days ago';
    }

    document.querySelectorAll('[data-sync-status][data-synced-at]').forEach(function (el) {
        var at = new Date(el.getAttribute('data-synced-at'));
        if (isNaN(at.getTime())) return;
        var staleAfter = parseFloat(el.getAttribute('data-stale-after')) || 36;
        var age = Date.now() - at.getTime();
        var text = el.querySelector('.sync-status-text');
        var partial = el.classList.contains('is-partial');
        var label = 'GitHub data synced ' + relative(age);
        if (age > staleAfter * 3600000) {
            el.classList.add('is-stale');
            label += ' · may be out of date';
        } else if (partial) {
            label += ' · some sources used cached data';
        }
        if (text) text.textContent = label;
        el.title = 'Last synchronized ' + at.toLocaleString();
    });

    // ── Broken images (deleted screenshots, offline hosts) ────
    function hideBroken(img) {
        var wrap = img.closest('.sp-image, .fp-image');
        if (wrap) wrap.style.display = 'none'; else img.style.display = 'none';
    }
    document.querySelectorAll('img[data-sync-img], .readme-body img').forEach(function (img) {
        if (img.complete && img.naturalWidth === 0 && img.getAttribute('src')) hideBroken(img);
        img.addEventListener('error', function () { hideBroken(img); });
    });

    // ── Project search / filter / sort ───────────────────────
    var grid = document.getElementById('sync-grid');
    if (!grid) return;
    var cards = Array.prototype.slice.call(grid.querySelectorAll('.sync-card'));
    var original = cards.slice();
    var search = document.getElementById('sync-search');
    var sort = document.getElementById('sync-sort');
    var chips = Array.prototype.slice.call(document.querySelectorAll('.sync-filter'));
    var empty = document.querySelector('[data-sync-empty]');
    var state = { q: '', tech: 'all', sort: 'default' };

    try {
        var saved = JSON.parse(sessionStorage.getItem('sync-filters') || 'null');
        if (saved) state = Object.assign(state, saved);
    } catch (e) { /* storage unavailable */ }

    function apply() {
        var q = state.q.trim().toLowerCase();
        var visible = 0;
        cards.forEach(function (c) {
            var techs = (c.getAttribute('data-tech') || '').split('|');
            var okTech = state.tech === 'all' || techs.indexOf(state.tech) !== -1;
            var okQ = !q || (c.getAttribute('data-name') || '').indexOf(q) !== -1 || techs.join(' ').indexOf(q) !== -1;
            var show = okTech && okQ;
            c.hidden = !show;
            if (show) visible++;
        });
        var ordered = original.slice();
        var num = function (c, k) { return parseFloat(c.getAttribute(k)) || 0; };
        var str = function (c, k) { return c.getAttribute(k) || ''; };
        if (state.sort === 'stars') ordered.sort(function (a, b) { return num(b, 'data-stars') - num(a, 'data-stars'); });
        if (state.sort === 'updated') ordered.sort(function (a, b) { return str(b, 'data-updated').localeCompare(str(a, 'data-updated')); });
        if (state.sort === 'newest') ordered.sort(function (a, b) { return str(b, 'data-created').localeCompare(str(a, 'data-created')); });
        ordered.forEach(function (c) { grid.appendChild(c); });
        if (empty) {
            empty.hidden = visible !== 0;
            if (visible === 0 && cards.length) empty.textContent = 'No projects match that search.';
        }
        chips.forEach(function (ch) {
            var on = ch.getAttribute('data-filter') === state.tech;
            ch.classList.toggle('is-active', on);
            ch.setAttribute('aria-pressed', on ? 'true' : 'false');
        });
        try { sessionStorage.setItem('sync-filters', JSON.stringify(state)); } catch (e) { /* ignore */ }
    }

    if (search) {
        search.value = state.q;
        search.addEventListener('input', function () { state.q = search.value; apply(); });
    }
    if (sort) {
        sort.value = state.sort;
        sort.addEventListener('change', function () { state.sort = sort.value; apply(); });
    }
    chips.forEach(function (ch) {
        ch.addEventListener('click', function () { state.tech = ch.getAttribute('data-filter'); apply(); });
    });
    if (!chips.some(function (ch) { return ch.getAttribute('data-filter') === state.tech; })) state.tech = 'all';
    apply();
})();
